INSERT INTO content (section, key, draft, published, updated_at) VALUES ('manual', 'pages', NULL, '[{"kind":"coverL"},{"kind":"title"},{"kind":"text","k":"Start here","t":"In the box","lines":[{"t":"ESP32 controller"},{"t":"Ultrasonic sensor — one per tank"},{"t":"12 V solenoid valve — one per tank"},{"t":"Relay module + pump contactor"},{"t":"5 V power supply"}],"ill":"box"},{"kind":"text","k":"Before you start","t":"Stay safe","lines":[{"t":"Switch off the pump at the MCB.","c":"warning"},{"t":"Pump wiring must be done by an electrician.","c":"warning"},{"t":"Keep your Wi-Fi password ready."}]},{"kind":"text","k":"Step 1","t":"Mount the sensors","lines":[{"t":"Fix the probe on the tank lid."},{"t":"Keep it at least 30 cm above the full level."}],"ill":"tank"},{"kind":"text","k":"Step 1 · cable","t":"One cable per tank","lines":[{"t":"Brown — 5 V","c":"wireBrown"},{"t":"Brown-white — GND","c":"wireBrownWhite"},{"t":"Blue — Trig","c":"wireBlue"},{"t":"Green — Echo","c":"wireGreen"}]},{"kind":"text","k":"Step 2","t":"Fit the valves","lines":[{"t":"One 12 V solenoid valve on each tank inlet."},{"t":"Relay IN1–IN3 switch valves 1–3."}],"ill":"valve"},{"kind":"text","k":"Step 3","t":"Wire the pump","lines":[{"t":"Relay IN4 drives the contactor coil."},{"t":"Use an MCB on the pump line."},{"t":"Electrician only.","c":"warning"}],"ill":"pump"},{"kind":"text","k":"Step 4","t":"Power on","lines":[{"t":"Slow blink — waiting for setup","c":"glow"},{"t":"Fast blink — connecting","c":"aqua"},{"t":"Steady — online","c":"teal"},{"t":"Double blink — safety stop","c":"warning"}]},{"kind":"text","k":"Step 5","t":"Set up in the app","lines":[{"t":"1. Sign up with your phone number."},{"t":"2. Scan the QR on the box."},{"t":"3. Pick your Wi-Fi and connect."},{"t":"4. Set your tank sizes."}],"ill":"phone"},{"kind":"text","k":"Built in","t":"Safety","lines":[{"t":"Valve opens 2 s before the pump."},{"t":"Stops on a dry run."},{"t":"Max run time — 30 min."},{"t":"60 s rest before restart."}],"ill":"shield"},{"kind":"text","k":"Help","t":"Need help?","lines":[{"t":"New router? Hold BOOT 5 s, then set up again."},{"t":"Call +91 98632 62589"},{"t":"cinzotechnologies@gmail.com"},{"t":"Chala Road, Luangmual"}]},{"kind":"end"},{"kind":"back"}]', 1794182400000);
